   if(act==='override'){v=await ask('Correct the meter reading',{label:'Corrected register value',input:'number',value:c.read?.registerValue??'',submit:'Release corrected value',text:`Reported ${num(c.read?.registerValue)}${exp!=null?` · expected about ${num(exp,1)}`:''} ${c.unit||c.read?.unit||''}`});if(v==null||v==='')return;}
   if(act==='accept'&&(c.disposition==='reject'||(c.confidence!=null&&c.confidence<0.3))){note=await ask('Release a read VEE rejected',{label:'Why release it as read?',submit:'Release as read',text:`VEE confidence ${c.confidence==null?'—':Math.round(c.confidence*100)+'%'} · disposition ${c.disposition||'—'}`});if(!note)return;}
   // A case completed while its order is open: warned on the page and by the engine's notice, never blocked.
